import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/data/inventory.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT NOT NULL,
        name TEXT NOT NULL,
        category TEXT,
        price REAL,
        quantity INTEGER,
        warehouse_id INTEGER
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        org_id TEXT NOT NULL,
        permissions TEXT NOT NULL
    )''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'missing api key'}), 401
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT org_id, permissions FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'invalid api key'}), 403
        g.org_id = row['org_id']
        g.permissions = row['permissions'].split(',')
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/products/search', methods=['GET'])
@require_auth
def search_products():
    """Search products with flexible filtering.
    Supports: category, warehouse_id, price_min, price_max, sort_by, order
    """
    if 'read' not in g.permissions:
        return jsonify({'error': 'insufficient permissions'}), 403

    category = request.args.get('category', '')
    warehouse_id = request.args.get('warehouse_id', '')
    price_min = request.args.get('price_min', '')
    price_max = request.args.get('price_max', '')
    sort_by = request.args.get('sort_by', 'name')
    order = request.args.get('order', 'ASC')

    conditions = []
    params = []

    if category:
        conditions.append('category = ?')
        params.append(category)
    if warehouse_id:
        conditions.append('warehouse_id = ?')
        params.append(warehouse_id)
    if price_min:
        conditions.append('price >= ?')
        params.append(float(price_min))
    if price_max:
        conditions.append('price <= ?')
        params.append(float(price_max))

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Build query with sort - sort_by is validated against allowed columns
    allowed_columns = ('name', 'price', 'quantity', 'sku', 'category')
    if sort_by not in allowed_columns:
        sort_by = 'name'

    # Order direction
    query = f"SELECT id, sku, name, category, price, quantity, warehouse_id FROM products WHERE {where_clause} ORDER BY {sort_by} {order}"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'products': [dict(r) for r in results], 'count': len(results)})
    except Exception as e:
        app.logger.error(f'Query error: {e}')
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
@require_auth
def get_product(product_id):
    if 'read' not in g.permissions:
        return jsonify({'error': 'insufficient permissions'}), 403
    db = get_db()
    row = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/api/v1/products', methods=['POST'])
@require_auth
def create_product():
    if 'write' not in g.permissions:
        return jsonify({'error': 'insufficient permissions'}), 403
    data = request.get_json()
    db = get_db()
    db.execute(
        'INSERT INTO products (sku, name, category, price, quantity, warehouse_id) VALUES (?, ?, ?, ?, ?, ?)',
        (data['sku'], data['name'], data.get('category'), data.get('price', 0), data.get('quantity', 0), data.get('warehouse_id'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
